# --- the cases, shared verbatim with `gold419.py` (which ran them on the baseline) ------------------------------------
# A case writes one new project's launcher artifacts into a test-owned output directory from a synthetic plan. The
# launcher's pure seams run for real (the default role CLIs, the layout payload, the `.switchyard` directory, the JSON
# reader and the atomic writer) and so does the desktop-policy validator; the seams that read accounts or the host (the
# session directory, the shared pane launcher, the director's onboarding seed) stand in, recorded, and so does the
# workflow projection (a deterministic stand-in that drops a role and re-slots the rest). Every call is recorded, every
# line printed, and every file's bytes and mode afterwards.
DEFAULT = {"call": "write"}
ROLE_COUNTS = {f"{n} implementers": {"call": "write", "implementers": [f"i{k}" for k in range(n)]} for n in (0, 1, 2, 3, 4, 6)}
