def test_either_import_order_gives_one_set_of_objects_and_the_defaults() -> None:
    for order in (("scripts.new_project_artifacts", "scripts.team_launcher"), ("scripts.team_launcher", "scripts.new_project_artifacts")):
        result = python("import importlib, inspect; "
                        f"[importlib.import_module(n) for n in {order!r}]; "
                        "import scripts.team_launcher as t, scripts.new_project_artifacts as m, scripts.ticket_board.project_provision as pp; "
                        "d = lambda f, n: inspect.signature(f).parameters[n].default; "
                        f"print(all(getattr(t, n) is getattr(m, n) for n in {MOVED!r}), "
                        "all(d(f, 'implementer_roles') is pp.DEFAULT_PROJECT_IMPLEMENTER_ROLES is t.DEFAULT_PROJECT_IMPLEMENTER_ROLES "
                        "for f in (m._new_project_launcher_config_payload, m.write_new_project_launcher_artifacts)) "
                        "and d(m.write_new_project_launcher_artifacts, 'print_func') is print, "
                        "not hasattr(m, 'launcher') and not hasattr(m, 'ProjectBoardProvision'))")
