def test_the_rules_hold_in_the_measured_record() -> None:
    def answer(label):
        return GOLDEN[label]["answer"]

    def config(label):
        return json.loads(GOLDEN[label]["files"]["out/p419.json"][1])

    order = [c[0] for c in GOLDEN["write: the default implementers"]["calls"]]
    layout_at = order.index("_new_project_layout_payload")
    check(layout_at < order.index("_new_project_launcher_config_payload"), f"the layout is built and written before the config: {order}")
    roles = [(r["role"], r.get("slot"), r.get("detached")) for r in config("write: explicit role CLIs beyond the cap")["roles"]]
    check(roles[:6] == [(f"r{k}", k, None) for k in range(6)] and all(d is True for _, _, d in roles[6:])
          and GOLDEN["write: explicit role CLIs beyond the cap"]["printed"], f"six slotted, the rest detached and said so: {roles}")
    check([r["role"] for r in config("write: explicit role CLIs, duplicated")["roles"]] == ["director", "main", "qa"], "each role once, the first choice kept")
    models = {r["role"]: (r.get("model"), r.get("effort")) for r in config("write: models and efforts, some blank")["roles"]}
    check(models["director"] == ("opus", "high") and models["main"] == (None, None) and models["audit"] == (None, None), f"blank choices are left out: {models}")
    modes = {f: m for f, (m, _c) in GOLDEN["write: a umask that leaves group write"]["files"].items()}
    check(modes["out/p419.json"] == "0o644", f"the config never keeps group or other write: {modes}")
    check(answer("write: an invalid desktop policy")["raised"] == "DesktopAccessError" and "out/p419.json" in GOLDEN["write: an invalid desktop policy"]["files"],
          "an invalid desktop policy is refused after the config is written, as on the baseline")


def test_every_launcher_seam_is_reached() -> None:
    expected = {name for reads in SEAMS.values() for name in reads if callable(getattr(t, name, None)) and not isinstance(getattr(t, name), type)}
    check(expected <= REACHED, f"a recorder on the launcher reached every seam: missing {sorted(expected - REACHED)}")


STRUCTURE = ("test_the_module_loads_only_the_provision_modules_at_import", "test_either_import_order_gives_one_set_of_objects_and_the_defaults",
             "test_the_seams_read_through_the_launcher_and_nothing_bound", "test_the_launcher_reexports_the_six_and_its_readers_reach_them_there")
LAST = ("test_every_launcher_seam_is_reached",)


def main() -> int:
    names = sorted(name for name, value in globals().items() if name.startswith("test_") and callable(value))
    for name in [*STRUCTURE, *(name for name in names if name not in STRUCTURE + LAST), *LAST]:
        globals()[name]()
    print(f"new_project_artifacts_boundary_test: {CHECKS} checks ok")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
